"""Retain classification and per-source component mappings."""
import importlib.util,json
from pathlib import Path
H=Path(__file__).resolve().parent
s=importlib.util.spec_from_file_location('g',H.with_suffix('.py'));g=importlib.util.module_from_spec(s);s.loader.exec_module(g)
source=json.loads((H/'source.json').read_text());kp=source['kp'];lines=['# Classification','',f"Database math, lineage 01a12a15-3e0a-75a1-9dac-f8b8c5d5c3f1, captured basis {source['basis']}. All seven practice sources and canonical e-464 read together with generator registration; no existing generator. Native inventory counts 3 easy and 3 moderate, deficits 2 each. No supplied .generated file.",'','| Difficulty | Field contracts | Markdown/value templates | Profiles | Plot rating |','| --- | --- | --- | --- | --- |','| Easy observed | radio selection, blank field-1 | 3 observed; 1 authored legacy completion | 3 complete radio profiles; blank has none | none |','| Moderate observed | radio selection, blank field-1 | 3 | 2 complete radio profiles; blank has none | none |','| Hard | none observed | 0 supported | 0 | none |','','q-2204 is unrated, with a five-choice bank but no marker or solution. Its simple sine primitive is classified easy locally based on rated q-10061; the marker follows exact differentiation and a fixed solution is authored. Source remains unchanged. Three rated easy and three rated moderate questions retain their observed labels. Missing hard evidence bounds this implementation, rather than proving the KP can never have hard questions. New source evidence reopens classification.','','Each source is retained as its own render contract; changed numbers within that contract are variants. Sine indefinite prompts differ in variable/notation and solution completeness; cosine includes signed slope and nonzero shift. Definite sine radio and blank variants have different field/Markdown contracts; the shifted sine problem has different substitution bounds and bank. The cosine definite blank uses a pi slope and numerical x bounds. Canonical e-464 illustrates sine with fractional slope but contributes no practice inventory.']
(H/'classification.md').write_text('\n'.join(lines)+'\n')
items=[];md=['# Template extraction','','General pattern: substitute u=b*x+c, divide dx by nonzero b, integrate sine/cosine, restore the original variable or transform both definite bounds. Return a complete antiderivative including C or an exact definite scalar. Preserve each source field key, field shape, bank count and supplied solution. No inferred misconception feedback is presented.','','Policy extension: for positive integer k in 1..12, transport the entire source problem by x -> k*x, original bounds -> bounds/k and every primitive/scalar bank value -> its transported value/k. This deliberately narrow transport policy is mathematical and reproducible; it does not claim unobserved conceptual distractor recipes. Positive k preserves endpoint order. Original parameters occur at k=1. Source signed slope -9, positive shift 3, pi/3 shift, pi/4 slope, amplitudes 1,5,9 and variable z are all retained. Arbitrary amplitudes, shifts and negative dilations are outside this version.','','All numerical source components are preserved in source.json; source.edn retains exact typed IDs and refs. Each mapping below binds the complete bank, not pooled distractors.']
for sid,q in g.sources().items():
 d=g.DATA[sid];f=q[':question/answer-fields'][0];r=g.generate(d[0],0,sid,{'k':1});nf=r['question'][':question/answer-fields'][0]
 item={'source':sid,'entity':q[':db/id'],'level':d[0],'observed_difficulty':q.get(':question/difficulty'),'template':sid,'field_key':f[':answer-field/key'],'field_type':f[':answer-field/type'][':db/ident'],'plot':'none','parameters':{'function':d[1],'amplitude':str(d[2]),'slope':str(d[3]),'shift':str(d[4]),'lower':str(d[5]),'upper':str(d[6])},'source_prompt':q[':question/problem'],'source_solution':q.get(':question/worked-solution'),'choices':[]}
 md+=['','## '+sid,'',q[':question/problem'],'',f"Parameters: {item['parameters']}. Field {item['field_key']} ({item['field_type']}); plot none.",'','Fixed sequence: u substitution and dx factor; definite bound table when applicable; transformed integral; trig antiderivative; exact endpoint evaluation or back substitution. Exact supplied solution retained at k=1; variant notation uses one aligned block. q-2204 completion is explicit authored content.']
 for i,(a,expr) in enumerate(zip(f[':answer-field/choices'],d[7])):
  entry={'source_answer_id':a[':answer/id'],'source_field_id':f[':answer-field/id'],'exact_source_value':a[':answer/value'],'base_symbolic_expression':str(expr),'recipe':'('+str(expr)+').subs(x,k*x)/k'+(' + arbitrary C' if d[5] is None else ''),'profile':sid,'complete_value_replayed':True,'correct':nf[':answer-field/choices'][i][':answer/id']==nf[':answer-field/correct'][1],'interpretation':'observed expression; misconception interpretation unresolved'}
  item['choices'].append(entry);md+=['',f"- Option {i+1}: `{a[':answer/value']}`; recipe `{entry['recipe']}`; source owned answer {a[':answer/id']}; correct={entry['correct']}."]
 items.append(item)
(H/'template-components.json').write_text(json.dumps(items,indent=2)+'\n');(H/'template-extraction.md').write_text('\n'.join(md)+'\n')
(H/'plot-extraction.md').write_text('# Plot extraction\n\nAll seven practice sources and canonical e-464 contain text, LaTeX and substitution tables only. No image/plot/diagram references in prompts, choices or solutions. Each template rating is none. Tables are instructional bound mappings, not plots. No new assets or plot generator required.\n')
(H/'README.md').write_text('# Linear trigonometric integrals generator\n\nRun `python3 generate/scratch/17592186068915.py --difficulty easy --count 5 --seed 1915 --format json`; the script selects the repository SymPy runtime when necessary. Moderate is also supported; hard is explicitly unsupported.\n\nRun `.venv/bin/python generate/scratch/17592186068915/validate.py` for exhaustive printed-math, exact source-bank replay and real engine grading; then `.venv/bin/python generate/scratch/17592186068915/replenish.py` for additive locked commits and receipt recovery. Source evidence, component recipes, classification, review and hashes remain in this package.\n\nAll questions use stable content/profile identities and field-owned answers. The fingerprint ignores seed, choice order, identities, variable renaming and solution prose. Source and canonical content and learner history remain intact. Native difficulty labels are preserved; the legacy completion is explicitly authored. See capabilities.json for finite counts and the unfilled hard exception.\n')
